}, {
  "tStartMs": 2080878,
  "dDurationMs": 2069,
  "segs": [ {
    "utf8": "在我大概20出頭的時候 "
  } ]
}, {
  "tStartMs": 2082947,
  "dDurationMs": 1518,
  "segs": [ {
    "utf8": "就遇到了解嚴"
  } ]
}, {
  "tStartMs": 2084465,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "然後解嚴之後呢"
  } ]
}, {
  "tStartMs": 2085967,
  "dDurationMs": 3003,
  "segs": [ {

text:
    "utf8": "因為你就可以開始吸收的東西 就多了"
  } ]
}, {
  "tStartMs": 2088970,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "有的人就開始看日劇"
  } ]
}, {
  "tStartMs": 2090772,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "因為以前在戒嚴時期"
  } ]
}, {
  "tStartMs": 2092974,
  "dDurationMs": 3103,
  "segs": [ {
    "utf8": "還不能夠直接播日語的日劇"
  } ]
}, {
  "tStartMs": 2096077,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "後來就是因為解嚴"
  } ]
}, {
  "tStartMs": 2097779,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "然後頻道也開放"
  } ]
}, {
  "tStartMs": 2099781,
  "dDurationMs": 2285,
  "segs": [ {
    "utf8": "然後各種的戲劇都進來"
  } ]
}, {
  "tStartMs": 2102066,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "然後我在那段時間也開始去接觸"
  } ]
}, {
  "tStartMs": 2104268,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "到不同的歷史的書籍"
  } ]
}, {
  "tStartMs": 2106170,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "因為自己也興趣"
  } ]
}, {
  "tStartMs": 2107271,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "好 就看"
  } ]
}, {
  "tStartMs": 2108673,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "然後你會發現說"
  } ]
}, {
  "tStartMs": 2109774,
  "dDurationMs": 2803,
  "segs": [ {
    "utf8": "原來對於那段台灣的歷史"
  } ]
}, {
  "tStartMs": 2112577,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "有一些是我們以前根本不知道"
  } ]
}, {
  "tStartMs": 2114679,
  "dDurationMs": 2803,
  "segs": [ {
    "utf8": "或者是以前是用不同的角度在看"
  } ]
}, {
  "tStartMs": 2117482,
  "dDurationMs": 2485,
  "segs": [ {
    "utf8": "然後慢慢的我又一頭栽入到"
  } ]
}, {
  "tStartMs": 2119967,
  "dDurationMs": 1519,
  "segs": [ {
    "utf8": "日本的近代史 "
  } ]
}, {
  "tStartMs": 2121486,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "就為什麼會喜歡坂本龍馬"
  } ]
}, {
  "tStartMs": 2123171,
  "dDurationMs": 1901,
  "segs": [ {
    "utf8": "幕末這些歷史 "
  } ]
}, {
  "tStartMs": 2125072,
  "dDurationMs": 1202,
  "segs": [ {
    "utf8": "我的意思就是說"
  } ]
}, {
  "tStartMs": 2126274,
  "dDurationMs": 3703,
  "segs": [ {
    "utf8": "當我試著去找到一些寄託的東西"
  } ]
}, {
  "tStartMs": 2129977,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "這些寄託"
  } ]
}, {
  "tStartMs": 2130778,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": " 尤其是這些知識的寄託"
  } ]
}, {
  "tStartMs": 2133181,
  "dDurationMs": 2385,
  "segs": [ {
    "utf8": "也許它也是一開始是從戲劇來的"
  } ]
}, {
  "tStartMs": 2135566,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "像我們可能看了大河劇"
  } ]
}, {
  "tStartMs": 2137468,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "看了坂本龍馬這個人物"
  } ]
}, {
  "tStartMs": 2139270,
  "dDurationMs": 2502,
  "segs": [ {
    "utf8": "對這個人有興趣 才開始去走"
  } ]
}, {
  "tStartMs": 2141772,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "所以很多人好奇說"
  } ]
}, {
  "tStartMs": 2143274,
  "dDurationMs": 1735,
  "segs": [ {
    "utf8": "像我現在常常碰到我的觀眾 "
  } ]
}, {
  "tStartMs": 2145009,
  "dDurationMs": 1068,
  "segs": [ {
    "utf8": "他們都說"
  } ]
}, {
  "tStartMs": 2146077,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "哇 你的頻道跟別人不一樣"
  } ]
}, {
  "tStartMs": 2148179,
  "dDurationMs": 1752,
  "segs": [ {
    "utf8": "人家可能只是介紹旅遊 "
  } ]
}, {
  "tStartMs": 2149931,
  "dDurationMs": 1151,
  "segs": [ {
    "utf8": "日本的旅遊"
  } ]
}, {
  "tStartMs": 2151082,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "但是我會去講歷史"
  } ]
}, {
  "tStartMs": 2152567,
  "dDurationMs": 1901,
  "segs": [ {
    "utf8": "因為這個本身就是我的興趣"
  } ]
}, {
  "tStartMs": 2154468,
  "dDurationMs": 3704,
  "segs": [ {
    "utf8": "但是在這個興趣的吸收的過程當中"
  } ]
}, {
  "tStartMs": 2158172,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "我就慢慢去改變"
  } ]
}, {
  "tStartMs": 2159874,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "對一些事情的看法"
  } ]
}, {
  "tStartMs": 2161175,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "但是有很多跟我同樣年紀的朋友"
  } ]
}, {
  "tStartMs": 2163678,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "他們可能就是一直還在那個"
  } ]
}, {
  "tStartMs": 2165680,
  "dDurationMs": 2686,
  "segs": [ {
    "utf8": "所謂的敘事跟史觀裡面"
  } ]
}, {
  "tStartMs": 2168366,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "以至於對不同的黨派人"
  } ]
}, {
  "tStartMs": 2170368,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "就有一些存在的成見"
  } ]
}, {
  "tStartMs": 2172270,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "我懂"
  } ]
}, {
  "tStartMs": 2173171,
  "dDurationMs": 2702,
  "segs": [ {
    "utf8": "那我相信你在這段過程當中"
  } ]
}, {
  "tStartMs": 2175873,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "也是對這個應該深有體會"
  } ]
}, {
  "tStartMs": 2178276,
  "dDurationMs": 1518,
  "segs": [ {
    "utf8": "我覺得就是要無論如何 "
  } ]
}, {
  "tStartMs": 2179794,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "你還是要讓它"
  } ]
}, {
  "tStartMs": 2180778,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "我有時候比較不喜歡用融合這個詞"
  } ]
}, {
  "tStartMs": 2182880,
  "dDurationMs": 617,
  "segs": [ {
    "utf8": "就是因為 "
  } ]
}, {
  "tStartMs": 2183497,
  "dDurationMs": 1769,
  "segs": [ {
    "utf8": "融合這個詞聽起來有點像是"
  } ]
}, {
  "tStartMs": 2185266,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "你就是要大家全部都在一起"
  } ]
}, {
  "tStartMs": 2186968,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "都接受一個"
  } ]
}, {
  "tStartMs": 2187869,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "對 大融爐的感覺"
  } ]
}, {
  "tStartMs": 2190071,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "對 我不喜歡融合"
  } ]
}, {
  "tStartMs": 2190972,
  "dDurationMs": 1451,
  "segs": [ {
    "utf8": "那到底我要接受你的 "
  } ]
